import{_ as t,o as a,c as s,a0 as r}from"./chunks/framework.D4fUSYzX.js";const w=JSON.parse('{"title":"ADR 0162: A herdr-core start that stands in a worktree writes its own space label","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0162-a-herdr-core-start-that-stands-in-a-worktree-writes-its-own-space-label.md","filePath":"adr/0162-a-herdr-core-start-that-stands-in-a-worktree-writes-its-own-space-label.md"}'),n={name:"adr/0162-a-herdr-core-start-that-stands-in-a-worktree-writes-its-own-space-label.md"};function o(i,e,h,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0162-a-herdr-core-start-that-stands-in-a-worktree-writes-its-own-space-label" tabindex="-1">ADR 0162: A herdr-core start that stands in a worktree writes its own space label <a class="header-anchor" href="#adr-0162-a-herdr-core-start-that-stands-in-a-worktree-writes-its-own-space-label" aria-label="Permalink to &quot;ADR 0162: A herdr-core start that stands in a worktree writes its own space label&quot;">​</a></h1><p>Status: accepted Date: 2026-11-15 Amends ADR 0148&#39;s Adoption label rule: a start that stands in a git worktree the plane built writes the space label <code>herdr.space</code> as its own terminal name, and reads no label from the plane&#39;s own terminal.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0148-on-the-herdr-core-host-the-plane-adopts-its-start-into-the-space-not-the-tab.html">ADR 0148</a> decided that the plane copies the space label <code>herdr.space</code> from its own terminal onto every terminal a herdr-core start takes, so a start from a desktop terminal stands as its own tab in the plane&#39;s space in the Herdr desktop.</p><p>The measurement of 2026-11-15 on this machine found what that placement hides. The desktop&#39;s sidebar shows each space&#39;s <strong>worktrees</strong>: a space whose first terminal stands in a linked git worktree is drawn under the space whose first terminal stands in the main checkout, one row per worktree, named after the worktree&#39;s folder and showing its branch and its distance from the checkout. The machine state that day: the plane&#39;s own terminal stood in the main checkout under the desktop&#39;s space label, a Ticket handoff the plane had started stood in the git worktree the plane built for it, and a Consultation stood in the main checkout. Both started terminals carried the plane&#39;s space label and so stood as tabs inside the plane&#39;s space. No space stood in the handoff&#39;s worktree: that space&#39;s first terminal was the plane&#39;s own, in the main checkout. The handoff&#39;s worktree therefore never appeared in the desktop&#39;s worktree view, although the terminal ran in it.</p><p>The desktop&#39;s source settles the remedy. The app on this machine is <code>herdr-app</code> 0.1.15. Its <code>reconcile</code> adopts every live terminal that carries a non-empty <code>herdr.space</code> label and is not already shown, and when the label names a space the app does not know, its <code>adopt</code> <strong>creates the space</strong>: the space takes the terminal&#39;s live folder as its folder, and the terminal stands as the space&#39;s only terminal. The sidebar then shows the space, named after the worktree&#39;s folder, and its worktree row under the main checkout&#39;s space row. A terminal the operator or the plane removes makes the desktop drop its tab and, with it, its space.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>A herdr-core start that stands in a checkout other than the one it resolved into - on this host, the git worktree the plane built for it (ADR 0143) - writes the space label <code>herdr.space</code> as its own terminal name, and reads no label from the plane&#39;s own terminal.</strong> The desktop creates the space in the worktree, and the sidebar&#39;s worktree view shows that worktree under the space of the main checkout, or as the space&#39;s own row when the desktop shows no space in the checkout. The terminal name is the space id the plane writes: a live terminal&#39;s name is unique on the host, the name is deterministic for the terminal, and a terminal that goes away takes its space with it, so no label of a dead terminal outlives it.</p><p>A start that stands in the checkout it resolved into keeps ADR 0148&#39;s rule: it copies the plane&#39;s space label when the plane&#39;s terminal carries one, and no tab label at all. The plane&#39;s run labels, the write-once rule, and the forensics-only roster scoping stand unchanged.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A Ticket handoff on the herdr-core host shows in the desktop&#39;s sidebar as a worktree row under its checkout&#39;s space: the operator sees the worktree the Agent runs in, not only a tab in the plane&#39;s space. Consultations and other starts in the checkout keep standing as tabs in the plane&#39;s space, as ADR 0148 decided.</li><li>The plane reads its own terminal&#39;s record at the start only for a start in the checkout: a start in a worktree issues no <code>hc get</code> for the plane&#39;s terminal.</li><li>The desktop&#39;s side of the new rule - the space created in the worktree, its row under the checkout&#39;s space, and the space going away with its terminal - is an operator read. The verification record stands it as a walk to run after this change, and a desktop that changes its adoption rule is a measured break, the way ADR 0141 stated it.</li><li>A start in a worktree on the herdr host is untouched: the adoption labels are the herdr-core dialect&#39;s, and the herdr host&#39;s placements stay the desktop&#39;s and herdr&#39;s own.</li></ul>',11)])])}const k=t(n,[["render",o]]);export{w as __pageData,k as default};
